create table public.ops_onedrive_documents (document_id uuid primary key references public.ops_documents(id) on delete cascade, source_path text not null unique, onedrive_path text not null unique, onedrive_item_id text not null, size_bytes bigint not null check (size_bytes >= 0), sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'), verified_at timestamptz not null default now()); alter table public.ops_onedrive_documents enable row level security; revoke all on public.ops_onedrive_documents from public, anon, authenticated; grant select, insert, update, delete on public.ops_onedrive_documents to service_role;